{'command': 'cd /tmp; python3 -c "
import json
with open('trajectory.jsonl') as f:
    lines=[json.loads(l) for l in f if l.strip()]

def text_of(content):
    out=[]
    if isinstance(content,str):
        return content
    for part in content:
        if not isinstance(part,dict): continue
        t=part.get('type')
        if t=='text':
            out.append('[TEXT] '+part.get('text',''))
        elif t=='thinking':
            out.append('[THINKING] '+part.get('thinking','')[:1500])
        elif t=='tool_use':
            out.append('[TOOL_USE '+str(part.get('name'))+'] input='+json.dumps(part.get('input'))[:1200])
        elif t=='tool_result':
            c=part.get('content')
            s=c if isinstance(c,str) else json.dumps(c)
            out.append('[TOOL_RESULT] '+ (s[:1200] if s else ''))
        else:
            out.append('['+str(t)+']')
    return '\n'.join(out)

idx=0
for l in lines:
    if l.get('type') in ('assistant','user') and isinstance(l.get('message'),dict):
        role=l['message'].get('role')
        body=text_of(l['message'].get('content'))
        if not body.strip(): continue
        print('==== #%d %s ===='%(idx,role))
        print(body[:2500])
        print()
    idx+=1
